APC = off(HC1c, RYH1c, 0.42, 0.2, 1.74); AP_LOW = add(APC, [0.0, -0.16, 0.04]); AP_FLOOR = [AP_LOW[0], 0.12, AP_LOW[2]]
FA1c = [-0.25, CTOP + 0.01, -0.36]; FB1c = [0.2, CTOP + 0.01, -0.06]
