           *[k(r(0.36 + 0.14 * j), toon={**HKC(add(APC, [0, r(0.03 * (1 - j % 2)), 0])), 'bend': {**SP1c, 'neck': [0.17 if j % 2 == 0 else 0.0, 0, 0, 1, None]}, 'face': HOPE}, toonDur=0.07) for j in range(4)],
           *blink(0.95, HOPE, HKC(APC, bend=SP1c)),
