        *life(r(T3A + 0.3), r(T3B - 0.2), TF3, TAPK(REST3), blinks=[r(T3A + 0.38)], period=0.5, amp=0.016),
        *TAP3(T3B, HIT3B, {**TF3, 'mouth': 'smirk', 'lid': 0.6}),
