D4 = st.dur('S04'); POU4 = W('S04', 'L04', 3); DEUX4 = W('S04', 'L04', 6)
HEN4 = [0.3, 0.0, -0.5]; CR4 = [0.45, 0.0, 0.12]; PILE4 = [0.45, 0.22, 0.12]
