chkc('S04', C4, {'henComb': add(HEN4, [0, 1.18, 0.3]), 'beak': hen_beak(HEN4, RYH4), 'pileL': add(PILE4, [-0.3, 0.1, 0]), 'pileR': add(PILE4, [0.3, 0.1, 0]), 'pileTop': add(PILE4, [0, 0.33, 0]),
                 'drop': DROP4, 'hand': add(DROP4, [0.0, 0.11, 0.0]), 'heroHead': add(H4, [0, 2.0, 0])})
AF4 = FALL(REL4, DROP4, REST4, r(LAND4 - REL4))
GR4 = lambda p: add(p, [0.0, 0.11, 0.0])
HEROK4 = [k(0.0, look=REST4), k(0.0, toon={**HAND(GR4(DROP4), hr='grip'), 'bend': {'spine': [0.25, 0, 0, 1, None]}, 'face': HF}, toonDur=0.0),
          # the apple dangled (a little jiggle), then dropped: the mitten springs open and away so the forearm never hides the fall
          *[k(r(0.08 + 0.1 * j), toon={**HAND(GR4(add(DROP4, [0.0, 0.025 * (j % 2), 0.0])), hr='grip'), 'bend': {'spine': [0.25, 0, 0, 1, None]}, 'face': HF}, toonDur=0.06) for j in range(3)],
          k(REL4, toon={**HAND(add(DROP4, [0.14, 0.2, 0.0]), hr='open'), 'bend': {'spine': [0.22, 0, 0, 1, None]}, 'face': HF}, toonDur=0.06, toonEase='out'),
          k(0.75, toon={**HAND(add(DROP4, [0.55, 0.45, 0.0]), hr='open'), 'face': HF}, toonDur=0.3)]
APM4 = [(0.0, DROP4, 0.0, 'linear'), *[(r(0.08 + 0.1 * j), add(DROP4, [0.0, 0.025 * (j % 2), 0.0]), 0.06, 'inOut') for j in range(3)], *AF4]
C1_, C2_ = r(DEUX4 - 0.02), r(DEUX4 + 0.22)
st.shot('S04', 'grassland', setOpts=GSET, look=LOOKG, actors=[act('mec', H4, RY4, 'stand', 'neutral', keys=HEROK4)],
        props=[*GARDEN(4), P('caisse4', 'poCrate', pos=CR4, opts={'w': 0.82, 'h': 0.22, 'd': 0.55}),
               P('tas4', 'poApplePile', pos=PILE4, ry=r(yaw(PILE4, F4)), opts={'n': 2, 'add': [[0, 2], [LAND4, 3]], 'dropH': 0.0}),
               P('pomme4', 'poApple', pos=DROP4, ry=r(yaw(DROP4, F4)), opts={'r': 0.1, 'dir': [-0.3, 0.6, 1.0]}, keys=[*MOVES(APM4), k(r(LAND4 - 0.01), visible=False)]),
               HEN('poule4', HEN4, RYH4, teeth=[[0, 2]],
                   yaw=[[0, 0.45], [0.8, 0.45], [1.0, 0.0]], roll=[[0, 0], [1.1, 0], [1.4, 0.15], [C1_, 0.0]],
                   pitch=[[0, -0.35], [REL4, -0.35], [LAND4, 0.35], [0.8, 0.3], [1.0, 0.0], [C1_, 0.0], [r(C1_ + 0.05), -0.12], [r(C1_ + 0.16), 0.08], [r(C2_ + 0.04), -0.12], [r(C2_ + 0.2), 0.0]],
                   gaze=[[0, 0.6, -0.8], [REL4, 0.6, -0.8], [r(LAND4 - 0.04), 0.6, 0.7], [0.78, 0.0, 0.0]],
                   open=[[0, 0], [C1_, 0], [r(C1_ + 0.03), 1.0, 'lin'], [r(C1_ + 0.14), 1.0], [r(C1_ + 0.17), 0.08, 'lin'], [r(C2_ - 0.03), 0.08], [C2_, 1.0, 'lin']],
                   sparks=[[r(C1_ + 0.05), 0], [r(C2_ + 0.03), 1]], sparkSize=0.2,
                   squint=[[0, 0], [1.05, 0], [1.5, 0.45], [C1_, 0.6]], brow=[[0, 0.3], [0.62, 0.9], [0.9, 0.3], [1.2, 0.75], [1.38, 0.15], [1.56, 0.8], [C2_, 0.5]],
                   blinks=[0.25, r(D4 - 0.14)],
                   sq=[[0, 1, 1, 1], [LAND4, 1.0, 1.0, 1.0], [r(LAND4 + 0.05), 0.94, 1.08, 0.94], [r(LAND4 + 0.2), 1, 1, 1], [r(C1_ - 0.04), 1.06, 0.93, 1.06], [r(C1_ + 0.03), 0.95, 1.07, 0.95],
                       [r(C1_ + 0.16), 1.04, 0.96, 1.04], [r(C2_ + 0.02), 0.94, 1.08, 0.94], [r(C2_ + 0.2), 1.02, 0.98, 1.02], [r(C2_ + 0.32), 1, 1, 1]])],
        cams=[C4])
st.cue('thud', 'S04', LAND4, 0.22); st.cue('sfx:boing', 'S04', r(LAND4 + 0.02), 0.1); CLUCK('S04', 1.0, 0.25); st.cue('sfx:click', 'S04', r(C1_ + 0.16), 0.25); st.cue('sfx:ding', 'S04', r(C1_ + 0.05), 0.22); st.cue('sfx:ding', 'S04', r(C2_ + 0.03), 0.28)

# 5: « Expertise : deux vraies dents. » An expert in a white coat and a head mirror kneels at the hen's open beak with a big dental mirror (his arm
#    shoots in), peers; the head mirror glints; on « deux vraies dents » two grave nods (a squash each)
D5 = st.dur('S05'); DEUX5 = W('S05', 'L05', 1); VRA5 = W('S05', 'L05', 2)
HEN5 = [-0.05, 0.0, -0.5]; EX5 = [0.72, -0.3, -0.22]
F5 = [-0.75, 1.2, 2.1]; L5 = [0.3, 1.0, -0.35]
C5 = cam(0.0, F5, add(F5, [0.04, 0.0, -0.1]), L5, L5, lens=44, ease='inOut')
RYH5 = r((yaw(HEN5, F5) + yaw(HEN5, EX5)) / 2)
RYE5 = r(yaw(EX5, HEN5) + 0.55 * ((yaw(EX5, F5) - yaw(EX5, HEN5) + 540) % 360 - 180))
BK5 = hen_beak(HEN5, RYH5)
MIR5 = add(BK5, [0.02, 0.0, 0.0])
dx5 = [EX5[0] - BK5[0], 0.0, EX5[2] - BK5[2]]; n5 = math.hypot(dx5[0], dx5[2])
GRIP5 = [r(BK5[0] + dx5[0] / n5 * 0.34), r(BK5[1] - 0.02), r(BK5[2] + dx5[2] / n5 * 0.34)]
dm = [MIR5[i] - GRIP5[i] for i in range(3)]; nm = math.sqrt(sum(v * v for v in dm)); dm = [v / nm for v in dm]
MROT5 = [r(math.acos(max(-1, min(1, dm[1])))), r(math.atan2(dm[0], dm[2])), 0.0]
chkc('S05', C5, {'henComb': add(HEN5, [0, 1.18, 0]), 'beak': BK5, 'exHead': add(EX5, [0, 1.95, 0]), 'exMirror': add(EX5, [0, 2.05, 0.1]), 'grip': GRIP5})
EXF = {'lid': 0.5, 'mouth': 'line', 'brow': -0.35}
EXK = lambda g, **x: {'reach': {'R': R5(g, 1, 0.0), 'L': R5(off(EX5, RYE5, 0.3, 0.2, 0.95), 1, 0.0)}, 'hands': {'R': 'grip', 'L': 'open'}, 'hip': 0, **x}
G5A = off(EX5, RYE5, 0.35, -0.15, 1.15)
NOD = lambda t: [k(r(t - 0.05), toon={**EXK(GRIP5), 'sq': [1.03, 0.98, 1.03], 'bend': {'spine': [0.12, 0, 0, 1, None], 'neck': [-0.1, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.4}}, toonDur=0.05),
                 k(r(t + 0.04), toon={**EXK(GRIP5), 'sq': [1.08, 0.92, 1.08], 'bend': {'spine': [0.12, 0, 0, 1, None], 'neck': [0.3, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.75, 'brow': -0.6}}, toonDur=0.05, toonEase='out'),
                 k(r(t + 0.16), toon={**EXK(GRIP5), 'bend': {'spine': [0.12, 0, 0, 1, None], 'neck': [0.0, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.5}}, toonDur=0.08)]
EXK5 = [k(0.0, look=[BK5[0], 1.45, BK5[2]]), k(0.0, clip='kneel'), k(0.0, toon={**EXK(G5A), 'bend': {'spine': [0.12, 0, 0, 1, None]}, 'face': EXF}, toonDur=0.0),
        k(0.06, toon={**EXK(GRIP5), 'hose': 0.15, 'sq': [0.95, 1.05, 0.95], 'bend': {'spine': [0.12, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.3, 'brow': 0.2}}, toonDur=0.1, toonEase='out'),
        k(0.3, toon={**EXK(GRIP5), 'bend': {'spine': [0.12, 0, 0, 1, None], 'neck': [0.1, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.6, 'brow': -0.5}}, toonDur=0.15),
        *NOD(r(DEUX5 + 0.02)), *NOD(r(VRA5 + 0.12)),
        k(r(VRA5 + 0.4), look='camera', lookDur=0.2), k(r(VRA5 + 0.4), toon={**EXK(GRIP5), 'bend': {'spine': [0.12, 0, 0, 1, None]}, 'face': {**EXF, 'lid': 0.4, 'brow': 0.3}}, toonDur=0.15)]
MK5 = [k(0.0, to=MIR5, dur=0.0), k(0.06, squash=[1.0, 1.15, 1.0], dur=0.25)]
st.shot('S05', 'grassland', setOpts=GSET, look=LOOKG, actors=[act('expert', EX5, RYE5, 'kneel', 'neutral', keys=EXK5)],
        props=[*GARDEN(5), HEN('poule5', HEN5, RYH5, teeth=[[0, 2]], open=[[0, 0.2], [0.12, 1.0]], gaze=[[0, 0.8, 0.3], [0.5, 0.9, 0.5]], brow=[[0, 0.5]], blinks=[0.7, 1.55],
                                         sq=[[0, 1.06, 0.94, 1.06], [0.12, 0.96, 1.05, 0.96], [0.3, 1, 1, 1]], yaw=[[0, 0.1]], pitch=[[0, -0.15]]),
               P('miroir5', 'poDentalMirror', pos=GRIP5, rot=MROT5, rotOrder='YXZ', opts={'L': 0.42}),
               P('frontal5', 'poHeadMirror', on={'actor': 'expert', 'joint': 'head', 'offset': [0.0, 0.0, 0.0]}, opts={'y': 0.5, 'z': 0.12}),
               P('eclat5', 'poSparkle', on={'actor': 'expert', 'joint': 'head', 'offset': [0.0, 0.0, 0.0]}, opts={'pts': [[0.0, 0.55, 0.2, 0.55, 0.22]]})],
        cams=[C5])
st.cue('sfx:whoosh', 'S05', 0.06, 0.12); st.cue('sfx:ding', 'S05', 0.6, 0.15); st.cue('sfx:tick', 'S05', r(DEUX5 + 0.06), 0.12); st.cue('sfx:tick', 'S05', r(VRA5 + 0.16), 0.12)

# 5b: « La mutuelle a payé. » The counter from his side, close: the clerk, sour, pushes a big blank cheque at us; it slides out, she hangs on to its far
#     edge (her arm stretches like rubber), lets go on « payé », her arm snaps back and she folds her arms, lips pursed
D5b = st.dur('S05b'); PAY5b = W('S05b', 'L05', 7)
CL5b = [0.18, 0.0, -0.76]
F5b = [-0.15, 1.55, 2.55]; L5b = [0.1, 1.5, -0.5]
C5b = cam(0.0, F5b, add(F5b, [0.0, 0.0, -0.08]), L5b, L5b, lens=44, ease='inOut')
CH5A = [0.16, 1.3, -0.34]; CH5B = [0.02, 1.3, 0.3]; CH5C = [-0.4, 1.0, 1.3]
LET5 = r(PAY5b + 0.1)
chkc('S05b', C5b, {'clerkTop': add(CL5b, [0, 2.15, 0]), 'chequeA': CH5A, 'chequeB': CH5B, 'chequeBL': add(CH5B, [-0.38, 0, 0]), 'chequeBR': add(CH5B, [0.38, 0, 0])})
CHM5 = [(0.04, CH5B, 0.32, 'out'), (LET5, CH5C, 0.16, 'in')]
CHT5 = track(CH5A, CHM5)
SOUR = {'lid': 0.5, 'mouth': 'pout', 'brow': -0.6}
CLK5b = [k(0.0, look=add(CH5B, [0, 0.1, 0])), k(0.0, toon={**CK(add(CH5A, [0.3, 0.0, -0.02]), add(CH5A, [-0.3, 0.0, -0.02]), 'grip', 'grip'), 'face': SOUR}, toonDur=0.0),
         k(0.04, toon={**CK(add(CHT5(0.36), [0.36, 0.0, -0.02]), None, 'grip', 'rest'), 'bend': {'spine': [0.15, 0, 0, 1, None]}, 'face': SOUR}, toonDur=0.32, toonEase='out'),
         # she hangs on: the arm stretches, she leans back
         k(0.42, toon={**CK(add(CH5B, [0.31, 0.0, -0.02]), None, 'grip', 'rest'), 'hose': 0.22, 'sq': [0.97, 1.04, 0.97], 'bend': {'spine': [-0.12, 0, 0, 1, None]}, 'face': {**SOUR, 'mouth': 'clench', 'brow': -0.8}}, toonDur=0.1),
         k(r(LET5 - 0.04), toon={**CK(add(CH5B, [0.31, 0.0, -0.02]), None, 'grip', 'rest'), 'hose': 0.3, 'sq': [0.95, 1.06, 0.95], 'bend': {'spine': [-0.18, 0, 0, 1, None]}, 'face': {**SOUR, 'mouth': 'clench', 'brow': -0.9}}, toonDur=0.06),
         k(LET5, toon={**CK(add(CL5b, [0.3, 1.25, 0.3]), add(CL5b, [-0.3, 1.2, 0.3]), 'open', 'open'), 'sq': [1.08, 0.93, 1.08], 'face': {**SOUR, 'lid': 0.2, 'brow': 0.4, 'mouth': 'o'}}, toonDur=0.04, toonEase='out'),
         k(r(LET5 + 0.18), toon={**CK(off(CL5b, 0, 0.22, 0.12, 1.2), off(CL5b, 0, 0.24, -0.12, 1.16), 'rest', 'rest'), 'face': {**SOUR, 'lid': 0.6}}, toonDur=0.15)]
st.shot('S05b', 'whiteVoid', setOpts=CSET, actors=[act('guichet', CL5b, 0, 'stand', 'neutral', keys=CLK5b)],
        props=[COUNTER('5b', sign=False), P('cheque5b', 'poCheque', pos=CH5A, opts={'w': 0.62}, keys=[*MOVES(CHM5), k(0.42, squash=[1.1, 0.95, 1.0], dur=0.3), k(LET5, rotTo=[0.4, 0.3, 0.5], dur=0.16)])],
        cams=[C5b])
st.cue('sfx:paper', 'S05b', 0.04, 0.2); st.cue('sfx:stretch', 'S05b', 0.42, 0.15); st.cue('sfx:twang', 'S05b', LET5, 0.25); st.cue('sfx:kaching', 'S05b', r(PAY5b + 0.02), 0.2)

# 6: « Le pays a ressorti ses vieilles promesses. » A terrace of five narrow pastel houses seen along the row from a low camera at its end: the nearest
#    neighbour large in the foreground, the others shrinking away (the cascade reads as a diagonal); the five doors fly open one after the other from the
#    nearest (a hinge overshoot and wobble), five neighbours step out on their steps, each with a big yellowed envelope, take a breath (cheeks inflated) and
#    blow a big cloud of dust off it together on « promesses »; then breathing and a blink
D6 = st.dur('S06'); PROM6 = W('S06', 'L06', 6)
ROW = [0.0, 0.0, -3.0]; RW = 1.6
DOORX = [r((i - 2) * RW) for i in range(5)]
WHO6 = ['voisin4', 'voisin3', 'voisin2', 'voisin1', 'mamie']
P6A = [[x, 0.0, -3.35] for x in DOORX]; P6B = [[x, 0.0, -2.3] for x in DOORX]
F6 = [7.0, 1.12, -0.7]; L6 = [-0.2, 1.25, -2.56]
C6 = cam(0.0, F6, add(F6, [-0.25, 0.0, -0.06]), L6, L6, lens=36, ease='inOut')
def EHK(p, ry_):
    # both mittens on the envelope's two edges, along its own width (it faces the camera), a little behind it
    ax, nz = [math.cos(math.radians(ry_)), 0.0, -math.sin(math.radians(ry_))], [math.sin(math.radians(ry_)), 0.0, math.cos(math.radians(ry_))]
    e = lambda sd: [r(p[0] + sd * 0.22 * ax[0] - 0.03 * nz[0]), r(p[1] - 0.05), r(p[2] + sd * 0.22 * ax[2] - 0.03 * nz[2])]
    return HAND(e(-1), e(1), 'grip', 'grip')
OPEN6, STG6 = 0.04, 0.11
EW6 = 0.55
chkc('S06', C6, {f'head{i}': add(P6B[i], [0, 2.2, 0]) for i in range(5)} | {'feet4': P6B[4], 'env4': off(P6B[4], 45, 0.36, 0.0, 1.3), 'env0': off(P6B[0], 45, 0.36, 0.0, 1.3)})
env6, act6 = [], []
for i, (who, a, b) in enumerate(zip(WHO6, P6A, P6B)):
    j = 4 - i; td = r(OPEN6 + STG6 * j); t0 = r(td + 0.08); ry6 = r(yaw(b, F6) * 0.6)
    EN = lambda p: off(p, ry6, 0.36, 0.0, 1.3)
    em = [(t0, EN(b), 0.32, 'inOut')]; et = track(EN(a), em)
    tb = r(PROM6 + 0.02 * (i % 2))
    fc = {'lid': 0.35, 'mouth': 'smile', 'brow': 0.4}
    ery = r(yaw(EN(b), F6)); EH = lambda p: EHK(p, ery)
    ks = [k(0.0, look='camera'), k(t0, to=b, dur=0.32, clip='walk', face=ry6, ease='inOut'),
          *[k(r(t0 + 0.06 * q), toon={**EH(et(r(t0 + 0.06 * q + 0.05))), 'face': fc}, toonDur=0.06) for q in range(6)],
          *life(r(t0 + 0.4), r(tb - 0.36), fc, EH(EN(b)), ph=0.03 * i, period=0.6, amp=0.012),
          # the breath in: a stretch, the head back, the cheeks blown up
          k(r(tb - 0.32), toon={**EH(EN(b)), 'sq': [0.95, 1.07, 0.95], 'bend': {'neck': [-0.14, 0, 0, 1, None], 'spine': [-0.06, 0, 0, 1, None]}, 'face': {**fc, 'puff': 1.0, 'cheeks': 1.0, 'mouth': 'line', 'lid': 0.2, 'brow': 0.7}}, toonDur=0.16, toonEase='out'),
          k(r(tb - 0.08), toon={**EH(EN(b)), 'sq': [0.94, 1.08, 0.94], 'bend': {'neck': [-0.16, 0, 0, 1, None], 'spine': [-0.07, 0, 0, 1, None]}, 'face': {**fc, 'puff': 1.0, 'cheeks': 1.0, 'mouth': 'line', 'lid': 0.15, 'brow': 0.8}}, toonDur=0.06),
          # the blow: the head shoots forward, a squash, the cheeks empty
          k(tb, toon={**EH(EN(b)), 'sq': [1.06, 0.94, 1.06], 'bend': {'neck': [0.38, 0, 0, 1, None], 'spine': [0.1, 0, 0, 1, None]}, 'face': {**fc, 'puff': 0.2, 'mouth': 'o', 'lid': 0.7}}, toonDur=0.05, toonEase='out'),
          k(r(tb + 0.28), toon={**EH(EN(b)), 'sq': [0.99, 1.01, 0.99], 'bend': {'neck': [0.1, 0, 0, 1, None]}, 'face': {**fc, 'mouth': 'o', 'lid': 0.5}}, toonDur=0.12),
          *life(r(tb + 0.42), D6, {**fc, 'lid': 0.3}, EH(EN(b)), ph=0.04 * i, blinks=[r(D6 - 0.3 - 0.04 * i)], period=0.6, amp=0.012)]
    act6.append(act(who, a, ry6, 'stand', 'neutral', keys=ks))
    env6.append(P(f'lettre6_{i}', 'poOldLetter', pos=EN(a), ry=r(yaw(EN(b), F6)), opts={'w': EW6, 'dust': [r(tb + 0.02)], 'dustDur': 0.9}, keys=MOVES(em)))
DOOR6 = [[OPEN6, 0], [r(OPEN6 + 0.09), 1.0], [r(OPEN6 + 0.14), 0.87], [r(OPEN6 + 0.2), 1.0], [r(OPEN6 + 0.25), 0.975], [r(OPEN6 + 0.3), 1.0]]
st.shot('S06', 'grassland', setOpts={**GSET, 'clouds': 20}, look={'sunDir': [0.55, 0.8, 0.6]}, actors=act6,
        props=[P('rangee6', 'poRowHouses', pos=ROW, opts={'n': 5, 'w': RW, 'open': DOOR6, 'stagger': STG6, 'rev': True, 'slam': r(OPEN6 + 0.09), 'wob': 0.05, 'swing': 3.06}), *env6],
        cams=[C6])
for i in range(5): st.cue('sfx:carDoor', 'S06', r(OPEN6 + STG6 * i + 0.06), r(0.16 - 0.02 * i))
st.cue('gust', 'S06', r(PROM6 - 0.02), 0.16, 0.7)

# 6b: « Même condition. » Close on the nearest neighbour, an old lady, from along the row (the other doors behind her, her head clear of any lintel):
#     she pulls the letter out of her envelope and turns it to us: a drawing of a hen with teeth (the condition, no text); she raises her eyebrows and nods
D6b = st.dur('S06b')
M6 = P6B[4]; RYM6 = r(yaw(M6, F6) * 0.6)
F6b = [5.6, 1.2, -1.35]; L6b = [3.2, 1.52, -2.2]
C6b = cam(0.0, F6b, add(F6b, [-0.08, 0.0, -0.03]), L6b, L6b, lens=38, ease='out')
EN6b = off(M6, RYM6, 0.42, 0.14, 1.28)
chkc('S06b', C6b, {'letterTop': add(EN6b, [0, 0.55, 0]), 'envBottom': add(EN6b, [0, -0.17, 0]), 'top': add(M6, [0, 2.2, 0]), 'chin': add(M6, [0, 1.62, 0])})
MF = {'lid': 0.3, 'mouth': 'smile', 'brow': 0.6}
MHK = lambda p: EHK(p, r(yaw(EN6b, F6b)))
